draw(rotate(45,(0,0,1))*p,dashed);
draw(rotate(45,(0,0,1))*((1,0,0)--(-1,0,0)--(-1,0,2)--(1,0,2)--cycle));
draw(rotate(45,(0,0,1))*shift((0,0,2))*p);
draw(rotate(118,(0,0,1))*((1,0,0)--(1,0,2)));
[/asy]

